<?php

namespace Tests\Search;

use Ladb\CoreBundle\DataFixtures\UserFixtures;
use Ladb\CoreBundle\Entity\Event\Event;
use Tests\WebTestCase;
use Tests\XhrTrait;

/**
 * What each search of the site finds in the index of the fixtures. The cases: every facet of every
 * list, the search without facet (a word as typed, then in capitals without accents), the
 * typeaheads, and the searches of the show pages (similar contents, counts). Recorded on
 * Elasticsearch 5.6, before #31: a difference is a change of behaviour of the search.
 *
 * Each search of a request: type, sort, ids of the page in their order, total. "score": sorted by
 * relevance, an order that depends on the statistics of the index (number of documents, shards),
 * "random": by a random score from the seed, "count": a count only.
 */
final class FacetTest extends WebTestCase
{
    use XhrTrait;

    /**
     * @param array<string, string|int>                   $parameters
     * @param list<array{string, string, list<int>, int}> $expected
     *
     * @dataProvider provideSearches
     */
    public function testSearches(string $username, string $route, array $parameters, array $expected): void
    {
        // The periods count from now: the fixtures of the content must be younger
        if (str_contains($parameters['q'] ?? '', '@period:last30days') && static::findUser(UserFixtures::USER)->getCreatedAt() < new \DateTimeImmutable('-29 days')) {
            self::markTestSkipped('The fixtures are older than 30 days: castor -c test app:db:fixtures.');
        }
        // The days and the month of an event, which the fixtures put one month after their loading
        if (str_contains($parameters['q'] ?? '', '%event_')) {
            $startAt = static::getEntityManager()->getRepository(Event::class)->find(1)->getStartAt();
            $parameters['q'] = strtr($parameters['q'], ['%event_day%' => $startAt->format('Y-m-d'), '%event_month%' => $startAt->format('Y-m')]);
        }

        $client = static::createClientAs($username);
        $client->request('GET', static::generatePath($route, $parameters));

        self::assertSame(200, $client->getResponse()->getStatusCode());
        self::assertSame($expected, $client->getContainer()->get('tests.search_utils')->getSearches());
    }

